<div class="card p-3"><table class="table table-hover dt"><thead><tr><th>Kode</th><th>Booking</th><th>Travel</th><th>Dibayar</th><th>Potongan</th><th>Refund</th><th>Alasan</th><th>Status</th><th>Tindakan</th></tr></thead><tbody>
<?php foreach ($rows as $r): ?><tr><td><?= e($r->refund_code) ?></td><td><?= e($r->booking_code) ?></td><td><?= e($r->partner_name) ?></td><td><?= rupiah($r->paid_amount_snapshot) ?></td><td><?= rupiah($r->cancellation_fee) ?></td><td><?= rupiah($r->refund_amount) ?></td><td class="small"><?= e($r->reason) ?></td><td><?= badge($r->status) ?></td>
<td><?php if ($r->status === 'requested'): ?><form method="post" action="<?= site_url('admin/finance/refund_action/' . $r->id) ?>" class="d-inline-flex gap-1"><?= csrf_field() ?><input name="cancellation_fee" type="number" min="0" class="form-control form-control-sm" style="width:120px" placeholder="Potongan Rp"><button name="action" value="approve" class="btn btn-sm btn-success">Setujui</button><button name="action" value="reject" class="btn btn-sm btn-outline-danger">Tolak</button></form>
<?php elseif (in_array($r->status, ['approved', 'processing'])): ?><?= post_btn('admin/finance/refund_action/' . $r->id, 'Tandai Selesai (sudah ditransfer)', 'btn-primary', ['action' => 'complete'], 'Konfirmasi dana sudah dikembalikan ke customer?') ?><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div>
